import {
  invalidVisionV2Fixtures,
  validVisionV2Fixtures,
} from "@vem/shared/fixtures/vision-v2";
import {
  VISION_V2_BUNDLE_VERSION,
  VISION_V2_PROTOCOL,
  visionV2MessageSchema,
} from "@vem/shared/schemas/vision-v2";
import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

type Mode = "write" | "check";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "../..");
const sourceBundle = resolve(root, "packages/shared/generated/vision-v2");

function canonicalJson(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(",")}]`;
  if (value && typeof value === "object") {
    return `{${Object.entries(value as Record<string, unknown>)
      .sort(([left], [right]) => left.localeCompare(right))
      .map(([key, nested]) => `${JSON.stringify(key)}:${canonicalJson(nested)}`)
      .join(",")}}`;
  }
  return JSON.stringify(value);
}

function sha256(value: string): string {
  return createHash("sha256").update(value).digest("hex");
}

function generatedPythonModels(): string {
  return `# @generated by scripts/vision-v2-contracts/generate-bundle.ts\nfrom __future__ import annotations\n\nfrom pathlib import Path\nfrom typing import Any, Literal, Union\n\nfrom jsonschema import Draft202012Validator, FormatChecker\nfrom pydantic import BaseModel, ConfigDict, StrictBool, StrictInt, StrictStr\n\nPROTOCOL = "${VISION_V2_PROTOCOL}"\nCONTRACT_BUNDLE_VERSION = "${VISION_V2_BUNDLE_VERSION}"\n\n# The JSON Schema is generated from the VEM Zod source and is the semantic\n# authority. These strict Pydantic models give Vision typed boundary values;\n# parse_message first applies that exact generated schema to avoid a hand-kept\n# Python validation mirror drifting from the wire contract.\n_SCHEMA_PATH = Path(__file__).resolve().parents[1] / "vision-v2.schema.json"\n_SCHEMA = __import__("json").loads(_SCHEMA_PATH.read_text(encoding="utf-8"))\n_SCHEMA_VALIDATOR = Draft202012Validator(_SCHEMA, format_checker=FormatChecker())\n\nclass StrictModel(BaseModel):\n    model_config = ConfigDict(extra="forbid", strict=True)\n\nclass GarmentSource(StrictModel):\n    assetId: StrictStr\n    reference: StrictStr\n    digest: StrictStr\n    contentType: Literal["image/png"]\n    byteSize: StrictInt\n    template: Literal["tshirt_short_sleeve", "tshirt_long_sleeve"]\n\nclass ResultReference(StrictModel):\n    reference: StrictStr\n    digest: StrictStr\n    contentType: Literal["image/png"]\n    byteSize: StrictInt\n    width: StrictInt\n    height: StrictInt\n\nclass HelloPayload(StrictModel):\n    clientRole: Literal["machine"]\n    machineCode: StrictStr | None = None\n    contractDigest: StrictStr\n    capabilities: list[StrictStr]\n\nclass ReadyPayload(StrictModel):\n    serverName: StrictStr\n    serverVersion: StrictStr\n    contractDigest: StrictStr\n    cameraReady: StrictBool\n    fastReady: StrictBool\n    visionBusinessReady: StrictBool\n    capabilities: list[StrictStr]\n\nclass FastAttemptStartPayload(StrictModel):\n    attemptId: StrictStr\n    mode: Literal["fast"]\n    variantId: StrictStr\n    garment: GarmentSource\n\nclass AttemptAcceptedPayload(StrictModel):\n    attemptId: StrictStr\n    mode: Literal["fast"]\n\nclass AttemptProgressPayload(StrictModel):\n    attemptId: StrictStr\n    stage: Literal["generating"]\n\nclass AttemptCompletedPayload(StrictModel):\n    attemptId: StrictStr\n    result: ResultReference\n\nclass VisionV2Envelope(StrictModel):\n    protocol: Literal["${VISION_V2_PROTOCOL}"]\n    type: Literal["vision.hello", "vision.ready", "vision.try_on.attempt.start", "vision.try_on.attempt.accepted", "vision.try_on.attempt.progress", "vision.try_on.attempt.completed"]\n    messageId: StrictStr\n    timestamp: StrictStr\n    payload: dict[str, Any]\n\nPayload = Union[HelloPayload, ReadyPayload, FastAttemptStartPayload, AttemptAcceptedPayload, AttemptProgressPayload, AttemptCompletedPayload]\n\n_PAYLOADS = {\n    "vision.hello": HelloPayload,\n    "vision.ready": ReadyPayload,\n    "vision.try_on.attempt.start": FastAttemptStartPayload,\n    "vision.try_on.attempt.accepted": AttemptAcceptedPayload,\n    "vision.try_on.attempt.progress": AttemptProgressPayload,\n    "vision.try_on.attempt.completed": AttemptCompletedPayload,\n}\n\ndef parse_message(value: Any) -> VisionV2Envelope:\n    error = next(iter(_SCHEMA_VALIDATOR.iter_errors(value)), None)\n    if error is not None:\n        raise ValueError(f"invalid {PROTOCOL} message: {error.message}")\n    envelope = VisionV2Envelope.model_validate(value)\n    _PAYLOADS[envelope.type].model_validate(envelope.payload)\n    return envelope\n`;
}

function strictGeneratedPythonModels(): string {
  return generatedPythonModels()
    .replace(
      "from pathlib import Path",
      "import json\nfrom pathlib import Path\nfrom urllib.parse import parse_qsl, urlparse",
    )
    .replace(
      "from pydantic import BaseModel, ConfigDict, StrictBool, StrictInt, StrictStr",
      "from pydantic import BaseModel, ConfigDict, StrictBool, StrictInt, StrictStr, field_validator",
    )
    .replace(
      '_SCHEMA = __import__("json").loads(_SCHEMA_PATH.read_text(encoding="utf-8"))',
      '_SCHEMA = json.loads(_SCHEMA_PATH.read_text(encoding="utf-8"))',
    )
    .replace(
      "class GarmentSource(StrictModel):",
      `class TokenizedLoopbackReferenceModel(StrictModel):
    @field_validator("reference", check_fields=False)
    @classmethod
    def validate_tokenized_loopback_reference(cls, value: StrictStr) -> StrictStr:
        parsed = urlparse(value)
        first_token = next(
            (token for key, token in parse_qsl(parsed.query, keep_blank_values=True) if key == "token"),
            None,
        )
        if (
            parsed.scheme not in {"http", "https"}
            or parsed.hostname not in {"127.0.0.1", "localhost", "::1"}
            or parsed.username is not None
            or parsed.password is not None
            or not first_token
        ):
            raise ValueError("reference must be a tokenized loopback URL")
        return value

class GarmentSource(TokenizedLoopbackReferenceModel):`,
    )
    .replace(
      "class ResultReference(StrictModel):",
      "class ResultReference(TokenizedLoopbackReferenceModel):",
    );
}

function bundleFiles(): Map<string, string> {
  const schema = visionV2MessageSchema.toJSONSchema();
  return new Map([
    ["vision-v2.schema.json", `${canonicalJson(schema)}\n`],
    ["fixtures/valid.json", `${canonicalJson(validVisionV2Fixtures)}\n`],
    ["fixtures/invalid.json", `${canonicalJson(invalidVisionV2Fixtures)}\n`],
    ["python/vision_v2_models.py", strictGeneratedPythonModels()],
  ]);
}

function manifest(files: Map<string, string>): string {
  const fileDigests = Object.fromEntries(
    [...files.entries()].map(([path, contents]) => [path, sha256(contents)]),
  );
  return `${canonicalJson({
    schemaVersion: "vem-vision-v2-contract-bundle/v1",
    protocol: VISION_V2_PROTOCOL,
    bundleVersion: VISION_V2_BUNDLE_VERSION,
    bundleDigest: sha256(canonicalJson(fileDigests)),
    files: fileDigests,
  })}\n`;
}

function expectedFiles(): Map<string, string> {
  const files = bundleFiles();
  files.set("manifest.json", manifest(files));
  return files;
}

function applyBundle(target: string, mode: Mode): string[] {
  const expected = expectedFiles();
  const mismatches: string[] = [];
  for (const [relativePath, contents] of expected) {
    const path = join(target, relativePath);
    if (!existsSync(path) || readFileSync(path, "utf8") !== contents) {
      mismatches.push(path);
      if (mode === "write") {
        mkdirSync(dirname(path), { recursive: true });
        writeFileSync(path, contents, "utf8");
      }
    }
  }
  return mismatches;
}

function argumentsFrom(argv: string[]): {
  mode: Mode;
  visionRoot: string | undefined;
} {
  const mode: Mode = argv.includes("--check") ? "check" : "write";
  if (argv.includes("--local-only")) return { mode, visionRoot: undefined };
  const visionIndex = argv.indexOf("--vision-root");
  const visionRoot =
    visionIndex >= 0 && argv[visionIndex + 1]
      ? resolve(argv[visionIndex + 1])
      : resolve(root, "../vending-vision");
  return { mode, visionRoot };
}

export function generateVisionV2Bundle(
  mode: Mode,
  visionRoot: string | undefined,
): { changed: string[] } {
  const targets = [
    sourceBundle,
    ...(visionRoot ? [join(visionRoot, "contracts/vem_vision_v2")] : []),
  ];
  const changed = targets.flatMap((target) => applyBundle(target, mode));
  if (mode === "check" && changed.length > 0) {
    throw new Error(
      `Vision V2 contract bundle drifted:\n${changed.join("\n")}\nRun pnpm generate:vision-v2-contracts -- ${visionRoot ? `--vision-root ${visionRoot}` : "--local-only"}`,
    );
  }
  return { changed };
}

if (
  process.argv[1] &&
  resolve(process.argv[1]) === fileURLToPath(import.meta.url)
) {
  const { mode, visionRoot } = argumentsFrom(process.argv.slice(2));
  try {
    const result = generateVisionV2Bundle(mode, visionRoot);
    if (mode === "write") {
      process.stdout.write(
        `wrote ${result.changed.length} Vision V2 bundle files\n`,
      );
    }
  } catch (error) {
    process.stderr.write(
      `${error instanceof Error ? error.message : String(error)}\n`,
    );
    process.exitCode = 1;
  }
}
